 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]
    for r,c in marker:
        out[r][c] = 0
    mr0, mc0 = min(r for r,c in marker), min(c for r,c in marker)
    mr1, mc1 = max(r for r,c in marker), max(c for r,c in marker)
    # Vertical marker motifs specify vertical reflection; their stem direction
    # selects the side. The upward-pointing T reflects above the 4 motif.
    if mr1 - mr0 >= mc1 - mc0:
        rmin = min(r for r,c in src)
        for r,c in src:
            rr = 2*rmin - 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        cmax = max(c for r,c in src)
        for r,c in src:
            cc = 2*cmax + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    return out
